steps = [
    step("默认配置,文件放在 classpath:/static。/hello.txt、/app.js、/css/site.css 都是 200,Content-Type 分别是 text/plain、text/javascript、text/css;响应头只有 Last-Modified 和 Accept-Ranges: bytes,没有 Cache-Control,没有 ETag。/ 返回 static/index.html(欢迎页);classpath:/public/pub.txt 也能访问;HEAD 返回同样的头没有 body;不存在的 /nope.txt → 404 JSON。static 里有 over.txt、控制器里也有 /over.txt:返回的是控制器的内容,200 且没有 Last-Modified。", t=tl(S(1)), mark=lidx(S(1), '/over.txt', '/nope.txt'), done=lidx(S(1), 'GET /hello.txt', 'GET / ', 'GET /pub.txt', 'HEAD /hello.txt'), b=bars([['响应里的 Cache-Control 头个数', 0, '0'], ['响应里的 ETag 头个数', 0, '0'], ['同名时控制器赢(1=是)', 1, '是']], 1, mark=[0, 1], done=[2]), kv=KV([['默认静态文件响应头', 'Last-Modified、Accept-Ranges,没有缓存头'], ['欢迎页', '/ → static/index.html'], ['位置', 'static 与 public 都可访问'], ['同名', '控制器优先于静态文件']], ['默认静态文件响应头'])),
    step("条件请求与 Range。带 If-Modified-Since(取自上次响应的 Last-Modified)→ 304,没有 body;换成 2001 年的旧日期 → 200 完整内容。Range: bytes=0-4 → 206,body 01234,Content-Range: bytes 0-4/21,Content-Length: 5;Range: bytes=15- → 206,fghij 加换行共 6 字节,Content-Range: bytes 15-20/21;Range: bytes=999-1000(超出文件)→ 416,Content-Range: bytes */21。这些都不需要写代码,静态资源处理器自己就会回应。", t=tl(S(2)), mark=lidx(S(2), 'bytes=999-1000'), done=lidx(S(2), '条件请求:', 'Range: bytes=0-4', 'Range: bytes=15-'), b=bars([['If-Modified-Since 未变 → 状态码', 304, '304'], ['Range 0-4 → 状态码', 206, '206(5 字节)'], ['Range 超出范围 → 状态码', 416, '416']], 416, done=[0, 1], mark=[2]), kv=KV([['If-Modified-Since', '没变 304,旧日期 200'], ['Range', '206 + Content-Range'], ['超出范围', '416,Content-Range: bytes */21'], ['Accept-Ranges', '默认就是 bytes']], ['Range'])),
    step("三种缓存头配置。cache.period=3600 → Cache-Control: max-age=3600;cachecontrol.max-age=1d、cache-public=true、must-revalidate=true → Cache-Control: max-age=86400, must-revalidate, public;cachecontrol.no-cache=true → Cache-Control: no-cache。这些配置对所有静态资源一视同仁:/hello.txt 和 /app.js 拿到的是同一个值。", t=tl(S(3)), mark=lidx(S(3), 'cachecontrol.no-cache=true'), done=lidx(S(3), 'cache.period=3600', 'max-age=1d'), b=bars([['cache.period=3600 的 max-age 秒', 3600, '3600'], ['cachecontrol.max-age=1d 的 max-age 秒', 86400, '86400']], 86400, done=[0, 1]), kv=KV([['cache.period', '只设 max-age'], ['cachecontrol.*', '可组合 max-age、public、must-revalidate、no-cache…'], ['作用范围', '所有静态资源同一个值'], ['注意', '长缓存配全局,文件一改用户就拿旧的']], ['注意'])),
    step("内容哈希版本化(chain.strategy.content.enabled,paths=/**)加上 max-age=365d。ResourceUrlProvider 把 /app.js 变成 /app-0a5e4fedba3fc41d4a9932a0f872f7aa.js(文件内容的 MD5)。带哈希的路径 → 200,Cache-Control: max-age=31536000, public,并多了 ETag: W/\"0a5e4fedba3f…\";带上 If-Modified-Since → 304。写错哈希(全 0)→ 404。关键陷阱:没有版本的原路径 /app.js 同样得到 max-age=31536000, public——一年的缓存也套在了没有哈希的 URL 上,文件改了用户一年内都拿旧文件。", t=tl(S(4)), mark=lidx(S(4), '未版本化的原路径', '错误的哈希'), done=lidx(S(4), 'GET /url?path=/app.js', '带内容哈希的路径', '条件请求:'), b=bars([['带哈希路径的 max-age 秒', 31536000, '31536000'], ['原路径 /app.js 的 max-age 秒', 31536000, '31536000(同样一年!)'], ['错误哈希的状态码', 404, '404']], 31536000, done=[0], mark=[1, 2]), kv=KV([['哈希路径', '内容变哈希变,长期缓存安全'], ['ETag', '带哈希的路径多了弱 ETag'], ['原路径', '也套着一年的缓存,不安全'], ['要求', '页面里必须引用带哈希的 URL(靠 ResourceUrlProvider)']], ['原路径'])),
    step("固定版本前缀(chain.strategy.fixed.version=v7)。/app.js 被改写成 /v7/app.js,访问它 → 200,ETag: W/\"v7\";原路径 /app.js 也能访问,没有 ETag。固定版本只是路径里多了一段 v7,所有文件的 ETag 都是同一个 W/\"v7\"——版本是手动维护的,忘了改版本号,新旧文件就还是同一个 URL。", t=tl(S(5)), mark=lidx(S(5), 'ETag'), done=lidx(S(5), '/v7/app.js', '版本化路径', '原路径'), b=bars([['版本化路径的状态码', 200, '200'], ['原路径的状态码', 200, '200(仍可访问)']], 200, done=[0, 1]), kv=KV([['固定版本', '路径前缀 /v7/,手动改版本号'], ['ETag', 'W/"v7",所有文件一样'], ['对比内容哈希', '不用手改,内容变 URL 自动变'], ['原路径', '仍可访问']], ['对比内容哈希'])),
    step("spring.web.resources.add-mappings=false。/hello.txt、/pub.txt、/index.html 全部 404——静态资源和欢迎页一起关了;控制器的 /over.txt 仍然是 200。想用别的方式提供静态文件(例如自己配置 ResourceHandler 或交给 nginx)时才这样关。", t=tl(S(6)), mark=lidx(S(6), '/hello.txt', '/pub.txt', '/index.html'), done=lidx(S(6), '/over.txt'), b=bars([['/hello.txt 状态码', 404, '404'], ['/index.html 状态码', 404, '404'], ['控制器 /over.txt 状态码', 200, '200']], 404, mark=[0, 1], done=[2]), kv=KV([['add-mappings=false', '静态资源与欢迎页都 404'], ['控制器', '不受影响'], ['用途', '改用自己的 ResourceHandler 或前置服务器']], ['add-mappings=false'])),
    step("路径穿越写法。/%2e%2e/hello.txt、/css/..%2fhello.txt、/..%2f..%2fetc/passwd、/%2e%2e%2f%2e%2e%2fetc/passwd、/css/%5c..%5chello.txt → 400,是 Tomcat 的 HTML 错误页,请求没有进入 Spring;/css/../hello.txt 和 /css/%2e%2e/hello.txt → 404 JSON,没有读到 /hello.txt 的内容。试了的这几种写法,都没有拿到 static 目录之外或之上的文件。", t=tl(S(7)), mark=lidx(S(7), '/css/../hello.txt', '/css/%2e%2e/hello.txt'), done=lidx(S(7), '/%2e%2e/hello.txt', '/css/..%2fhello.txt', 'etc/passwd', '%5c'), b=bars([['400(Tomcat 拒绝)的写法个数', 5, '5'], ['404(Spring 找不到)的写法个数', 2, '2'], ['读到文件内容的写法个数', 0, '0']], 5, done=[0, 1, 2]), kv=KV([['编码的 ../ 或反斜杠', 'Tomcat 直接 400'], ['未编码或编码点的 ..', '404'], ['读到的文件', '0 个'], ['结论', '只试了 7 种写法,不是完整的安全测试']], ['结论'])),
]
